// Planner models - Study plan with exam date, subjects, tasks

import 'package:cloud_firestore/cloud_firestore.dart';

/// Study plan generated by AI
class StudyPlan {
  final String id;
  final String title;
  final DateTime examDate;
  final List<String> subjects;
  final int hoursPerDay;
  final List<String> weakTopics;
  final DateTime createdAt;
  final List<StudyDay> days;

  StudyPlan({
    required this.id,
    required this.title,
    required this.examDate,
    required this.subjects,
    required this.hoursPerDay,
    required this.weakTopics,
    required this.createdAt,
    required this.days,
  });

  factory StudyPlan.fromJson(Map<String, dynamic> json) => StudyPlan(
        id: json['id'] as String,
        title: json['title'] as String,
        examDate: json['examDate'] is Timestamp
            ? (json['examDate'] as Timestamp).toDate()
            : DateTime.parse(json['examDate'] as String),
        subjects: List<String>.from(json['subjects'] as List),
        hoursPerDay: json['hoursPerDay'] as int,
        weakTopics:
            (json['weakTopics'] as List).map((e) => e as String).toList(),
        createdAt: json['createdAt'] is Timestamp
            ? (json['createdAt'] as Timestamp).toDate()
            : DateTime.parse(json['createdAt'] as String),
        days: (json['days'] as List)
            .map((e) => StudyDay.fromJson(e as Map<String, dynamic>))
            .toList(),
      );

  factory StudyPlan.fromFirestore(DocumentSnapshot doc) {
    final data = doc.data() as Map<String, dynamic>;
    return StudyPlan.fromJson({'id': doc.id, ...data});
  }

  Map<String, dynamic> toJson() => {
        'title': title,
        'examDate': examDate.toIso8601String().split('T')[0],
        'subjects': subjects,
        'hoursPerDay': hoursPerDay,
        'weakTopics': weakTopics,
        'createdAt': createdAt.toIso8601String(),
        'days': days.map((d) => d.toJson()).toList(),
      };
}

/// Single day in the study plan
class StudyDay {
  final DateTime date;
  final List<StudyTask> tasks;

  StudyDay({
    required this.date,
    required this.tasks,
  });

  factory StudyDay.fromJson(Map<String, dynamic> json) => StudyDay(
        date: DateTime.parse(json['date'] as String),
        tasks: (json['tasks'] as List)
            .map((e) => StudyTask.fromJson(e as Map<String, dynamic>))
            .toList(),
      );

  Map<String, dynamic> toJson() => {
        'date': date.toIso8601String().split('T')[0],
        'tasks': tasks.map((t) => t.toJson()).toList(),
      };
}

/// Individual study task
class StudyTask {
  final String title;
  final String subject;
  final int estimatedMinutes;
  final String type; // study, review, practice, break
  final bool done;

  StudyTask({
    required this.title,
    required this.subject,
    required this.estimatedMinutes,
    required this.type,
    this.done = false,
  });

  factory StudyTask.fromJson(Map<String, dynamic> json) => StudyTask(
        title: json['title'] as String,
        subject: json['subject'] as String,
        estimatedMinutes: json['estimatedMinutes'] as int,
        type: json['type'] as String,
        done: json['done'] as bool? ?? false,
      );

  Map<String, dynamic> toJson() => {
        'title': title,
        'subject': subject,
        'estimatedMinutes': estimatedMinutes,
        'type': type,
        'done': done,
      };

  StudyTask copyWith({
    String? title,
    String? subject,
    int? estimatedMinutes,
    String? type,
    bool? done,
  }) {
    return StudyTask(
      title: title ?? this.title,
      subject: subject ?? this.subject,
      estimatedMinutes: estimatedMinutes ?? this.estimatedMinutes,
      type: type ?? this.type,
      done: done ?? this.done,
    );
  }
}

/// Plan statistics
class PlanStats {
  final StudyPlan plan;
  final int totalTasks;
  final int completedTasks;
  final int totalMinutes;
  final int completedMinutes;
  final double completionPercentage;

  PlanStats({
    required this.plan,
    required this.totalTasks,
    required this.completedTasks,
    required this.totalMinutes,
    required this.completedMinutes,
  }) : completionPercentage =
            totalTasks > 0 ? completedTasks / totalTasks : 0.0;

  factory PlanStats.fromPlan(StudyPlan plan) {
    int totalTasks = 0;
    int completedTasks = 0;
    int totalMinutes = 0;
    int completedMinutes = 0;

    for (final day in plan.days) {
      for (final task in day.tasks) {
        totalTasks++;
        totalMinutes += task.estimatedMinutes;
        if (task.done) {
          completedTasks++;
          completedMinutes += task.estimatedMinutes;
        }
      }
    }

    return PlanStats(
      plan: plan,
      totalTasks: totalTasks,
      completedTasks: completedTasks,
      totalMinutes: totalMinutes,
      completedMinutes: completedMinutes,
    );
  }
}
